import React,{act} from 'react';
import {createRoot} from 'react-dom/client';
import assert from 'node:assert/strict';
import {ParticipantWorkspace,AdminProfilePhoto} from '../../src/admin/ParticipantsPage';
import MediaLibraryPage from '../../src/admin/MediaLibraryPage';
import {AuditPage} from '../../src/admin/AuditPage';
import {CatalogWorkspace} from '../../src/admin/CatalogWorkspace';
const flush=async()=>act(async()=>{await new Promise(r=>setTimeout(r,10))});
export async function run(){
 const host=document.getElementById('root')!,root=createRoot(host);
 const click=async(label:string)=>{const b=[...host.querySelectorAll('button')].find(b=>b.textContent===label);assert.ok(b,label);await act(async()=>b.click());await flush()};
 const p={id:'p',lastName:'Тестов',firstName:'Участник',photoUrl:'private-ref',cars:[],performanceHistory:{registrations:Array.from({length:12},(_,i)=>({id:'r'+i,stage:{id:'s'+i,name:'Этап '+i,season:{year:2026}}}))}};
 await act(async()=>root.render(<ParticipantWorkspace item={p} displayCarName={()=>''} go={()=>{}}/>));await flush();
 assert.equal(host.querySelector('img')?.src,'blob:test-1');
 assert.equal(host.querySelectorAll('.participant-history-event').length,0,'history does not extend profile');
 await click('Выступления · 12');assert.equal(host.querySelectorAll('.participant-history-event').length,5);
 assert.equal(host.querySelectorAll('.participant-history-event[open]').length,0);
 await click('Дальше');assert.match(host.querySelector('.participant-history-event')!.textContent!,/Этап 5/);
 await click('Дальше');assert.equal(host.querySelectorAll('.participant-history-event').length,2);
 await click('Автомобили · 0');assert.match(host.textContent!,/Автомобилей нет/);
 await act(async()=>root.render(<AdminProfilePhoto key="no-photo" item={{id:'empty'}}/>));await flush();
 assert.deepEqual((globalThis as any).__released,['blob:test-1'],'leaving profile releases private object URL');
 assert.match(host.textContent!,/Фото не добавлено/);
 (globalThis as any).__photoFail=true;
 await act(async()=>root.render(<AdminProfilePhoto key="failure" item={p}/>));await flush();assert.match(host.textContent!,/Фото не загрузилось/);
 (globalThis as any).__photoFail=false;await click('Повторить');assert.ok(host.querySelector('img'));
 function Catalog({category='a'}:{category?:string}){const [selected,S]=React.useState('');return <CatalogWorkspace selection={selected} resetKey={category}><section><button className="catalog-list-select" onClick={()=>S('Pride')}>Pride</button></section><section>Модели Pride</section></CatalogWorkspace>}
 await act(async()=>root.render(<Catalog/>));await flush();
 assert.equal(host.querySelector('[data-pane]')?.getAttribute('data-pane'),'brands');
 await click('Pride');assert.equal(host.querySelector('[data-pane]')?.getAttribute('data-pane'),'models');
 await click('Марки');await click('Pride');assert.equal(host.querySelector('[data-pane]')?.getAttribute('data-pane'),'models','reselecting same brand reopens models');
 await act(async()=>root.render(<Catalog category="b"/>));await flush();assert.equal(host.querySelector('[data-pane]')?.getAttribute('data-pane'),'brands','category reset returns to brands');
 const Frame=({children}:any)=><main>{children}</main>,Empty=({text}:any)=><p>{text}</p>,ErrorPanel=({message}:any)=><p role="alert">{message}</p>,Loading=()=> <p>Загрузка</p>;
 await act(async()=>root.render(<MediaLibraryPage user={{id:'admin',role:'ADMIN',email:'admin@example.test'}} PageFrame={Frame} ErrorPanel={ErrorPanel} LoadingPage={Loading} Empty={Empty}/>));await flush();
 assert.equal(host.querySelectorAll('.media-library-card').length,10,'media starts with ten files');
 const nextMedia=host.querySelector('[aria-label="Следующая страница медиафайлов"]') as HTMLButtonElement;
 await act(async()=>nextMedia.click());await flush();assert.match(host.querySelector('.media-library-card')!.textContent!,/asset-10/);
 const replace=[...host.querySelectorAll('button')].find(b=>b.textContent==='Заменить')!;await act(async()=>replace.click());await flush();assert.equal((host.querySelector('.media-upload-panel') as HTMLDetailsElement).open,true,'replace opens upload section');
 const search=host.querySelector('[aria-label="Поиск медиафайлов"]') as HTMLInputElement;
 await act(async()=>{Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype,'value')!.set!.call(search,'asset-22');search.dispatchEvent(new window.Event('input',{bubbles:true}))});await flush();assert.equal(host.querySelectorAll('.media-library-card').length,1);assert.match(host.querySelector('.media-library-card')!.textContent!,/asset-22/);
 await act(async()=>root.render(<AuditPage PageFrame={Frame} ErrorPanel={ErrorPanel} LoadingPage={Loading} Empty={Empty} enumLabel={String} formatDate={String} roleName={{ADMIN:'Администратор',PARTICIPANT:'Участник'}}/>));await flush();
 assert.equal(host.querySelectorAll('.audit-entry').length,25);
 assert.match(host.textContent!,/Страница 1 из 5/);
 const nextAudit=host.querySelector('[aria-label="Следующая страница событий аудита"]') as HTMLButtonElement;
 await act(async()=>nextAudit.click());await flush();assert.equal((globalThis as any).__auditCalls.at(-1)[0],2,'audit requests the next server page');
 const filter=host.querySelector('.audit-toolbar select') as HTMLSelectElement;
 await act(async()=>{filter.value='Participant';filter.dispatchEvent(new window.Event('change',{bubbles:true}))});await flush();assert.deepEqual((globalThis as any).__auditCalls.at(-1).slice(0,3),[1,25,'Participant'],'filter resets server pagination');
 await act(async()=>root.unmount());
}
